-- Test-only reproduction of the inspected MVP1 table structure.
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text);
CREATE TYPE public.account_status AS ENUM('pending','active','suspended','disabled');
CREATE TYPE public.event_status AS ENUM('draft','published','cancelled','completed');
CREATE TYPE public.registration_status AS ENUM('registered','cancelled','attended','absent');
CREATE TABLE public.departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,code text NOT NULL,description text,email text,office_location text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.programs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),department_id uuid NOT NULL REFERENCES public.departments(id),name text NOT NULL,code text NOT NULL,degree_level text,description text,is_active boolean NOT NULL DEFAULT true,created_at timestamptz DEFAULT now());
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id),program_id uuid REFERENCES public.programs(id),department_id uuid REFERENCES public.departments(id),first_name text NOT NULL,last_name text NOT NULL,email text,student_or_staff_number text,phone text,avatar_path text,account_status public.account_status NOT NULL DEFAULT 'active',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.roles(id bigint PRIMARY KEY,code text NOT NULL UNIQUE,label text NOT NULL);
CREATE TABLE public.user_roles(user_id uuid REFERENCES public.profiles(id),role_id bigint REFERENCES public.roles(id),assigned_at timestamptz DEFAULT now(),PRIMARY KEY(user_id,role_id));
CREATE TABLE public.department_heads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),department_id uuid NOT NULL REFERENCES public.departments(id),user_id uuid NOT NULL REFERENCES public.profiles(id),office_hours text,academic_guidance text,starts_on date,ends_on date,created_at timestamptz DEFAULT now());
CREATE TABLE public.semesters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,number integer,academic_year text NOT NULL,starts_on date,ends_on date);
CREATE TABLE public.modules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL,title text NOT NULL,description text,objectives text,weekly_hours numeric,semester_id uuid REFERENCES public.semesters(id),responsible_teacher_id uuid REFERENCES public.profiles(id),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.program_modules(program_id uuid REFERENCES public.programs(id),module_id uuid REFERENCES public.modules(id),academic_year text,PRIMARY KEY(program_id,module_id,academic_year));
CREATE TABLE public.classrooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,building text,floor_label text,capacity integer,room_type text NOT NULL DEFAULT 'classroom');
CREATE TABLE public.timetables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),program_id uuid NOT NULL REFERENCES public.programs(id),semester_id uuid NOT NULL REFERENCES public.semesters(id),academic_year text NOT NULL,title text NOT NULL,file_id uuid,version_number integer NOT NULL DEFAULT 1,published_at timestamptz,is_current boolean NOT NULL DEFAULT false,created_by uuid REFERENCES public.profiles(id),created_at timestamptz DEFAULT now());
CREATE TABLE public.timetable_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),timetable_id uuid NOT NULL REFERENCES public.timetables(id),module_id uuid NOT NULL REFERENCES public.modules(id),teacher_id uuid REFERENCES public.profiles(id),classroom_id uuid REFERENCES public.classrooms(id),weekday integer NOT NULL CHECK(weekday BETWEEN 1 AND 7),starts_at time NOT NULL,ends_at time NOT NULL,session_type text NOT NULL DEFAULT 'lecture',session_date date,notes text);
CREATE TABLE public.events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organizer_id uuid NOT NULL REFERENCES public.profiles(id),title text NOT NULL,description text NOT NULL,category text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,location_text text NOT NULL,classroom_id uuid REFERENCES public.classrooms(id),capacity integer,status public.event_status NOT NULL DEFAULT 'draft',cover_file_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.event_program_targets(event_id uuid REFERENCES public.events(id),program_id uuid REFERENCES public.programs(id),PRIMARY KEY(event_id,program_id));
CREATE TABLE public.event_registrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES public.events(id),student_id uuid NOT NULL REFERENCES public.profiles(id),status public.registration_status NOT NULL DEFAULT 'registered',registered_at timestamptz NOT NULL DEFAULT now(),cancelled_at timestamptz,UNIQUE(event_id,student_id));
INSERT INTO public.roles(id,code,label) VALUES(1,'student','Étudiant'),(2,'teacher','Enseignant'),(3,'department_head','Chef de département'),(4,'organizer','Organisateur'),(5,'admin','Administrateur');
